insert into dai_mcq_rule (ma, ten, mo_ta, vi_du, nhom, ap_dung, du_phong, active) values
 ('R470', 'Bảng nhân/chia: nhầm sang kết quả liền kề', 'Nhớ nhầm bảng nhân/chia: lấy kết quả lệch đúng một lần số nhân (hoặc thương lệch 1).', '5 × 4 = 20 → 25; 18 : 3 = 6 → 7', 'tinh', array['NDB02040','NDB02041','NDB02042','NDB02052','NDB02783','NDB02784','NDB02050']::text[], false, true),
 ('R471', 'Đảo thứ tự các chữ số của kết quả', 'Tính đúng các chữ số nhưng viết ngược thứ tự (hàng chục ↔ hàng đơn vị).', '23 → 32', 'tinh', array['NDB02050','NDB02052','NDB02783','NDB02784','NDB02807','NDB02049']::text[], false, true),
 ('R473', 'Dùng phép đối: nhân thay chia hoặc chia thay nhân', 'Đọc đúng số liệu nhưng làm phép nhân khi phải chia (hoặc ngược lại) và lấy kết quả của phép sai.', '72 : 6 → 72 × 6 (hoặc 12 : 6 thành 12 × 6)', 'tinh', array['NDB02049','NDB02052','NDB02780']::text[], false, true),
 ('R474', 'Lấy kết quả của phép tính khác trong cùng dãy', 'Làm lẫn các phép tính trong một dãy và chép kết quả của phép tính kề bên.', 'Tính 10 × 7; 50 × 1 → viết 50 cho ý đầu', 'tinh', array['NDB02040','NDB02041','NDB02042','NDB02050','NDB02051','NDB02052','NDB02783','NDB02784']::text[], false, true),
 ('R475', 'Dãy số: sai bước nhảy (lệch 1 đơn vị bước)', 'Tìm quy luật dãy nhưng đếm với bước nhảy lớn hơn hoặc nhỏ hơn 1 đơn vị so với bước đúng.', 'Dãy 14; 21; 28: bước 7 → đếm bước 8 ra 36; 44', 'tinh', array['NDB02045','NDB02046','NDB02047','NDB02031']::text[], false, true),
 ('R476', 'Khối hộp chữ nhật: nhầm số mặt, số cạnh, số đỉnh', 'Nhớ lẫn số mặt (6), số cạnh (12), số đỉnh (8) của khối hộp chữ nhật.', 'Số cạnh nhiều hơn số đỉnh: 12 − 6 = 6 (lấy số mặt thay số đỉnh)', 'khai_niem', array['NDB02070']::text[], false, true),
 ('R477', 'Phân số đơn vị: đổi chỗ mẫu số giữa hai phân số', 'Viết đúng dạng 1/n nhưng gán nhầm mẫu số n của phần này cho phần khác.', 'Một phần hai; một phần năm → 1/5; 1/2', 'khai_niem', array['NDB02055']::text[], false, true),
 ('R478', 'Phân số đơn vị: viết tử số bằng mẫu số', 'Hiểu "một phần n" là n phần n (tử số bằng mẫu số) hoặc viết tử số theo số thứ tự.', 'Một phần hai → 2/2', 'khai_niem', array['NDB02055']::text[], false, true),
 ('R479', 'Tìm số bị chia/số chia: lấy luôn một số đã cho làm đáp số', 'Không thực hiện phép tính ngược mà chép một trong các số đã cho (số chia hoặc thương) làm kết quả.', '... : 4 = 9 → 4 hoặc 9', 'tinh', array['NDB02049']::text[], false, true),
 ('R480', 'Tìm số hạng chưa biết: bỏ sót một số hạng đã biết', 'Lấy tổng trừ chỉ một trong các số hạng đã biết, quên trừ số hạng còn lại.', '12 + 28 + ... = 60 → 60 − 12 = 48', 'tinh', array['NDB02038']::text[], false, true),
 ('R481', 'Số tròn trăm: nhầm số tròn trăm bé nhất có ba chữ số', 'Lấy nhầm số tròn trăm (200 thay vì 100, hoặc 1 000).', 'Thêm 35 được số tròn trăm bé nhất có ba chữ số → 200 − 35 = 165', 'khai_niem', array['NDB02038']::text[], false, true),
 ('R482', 'Lập số từ thẻ số: bỏ qua điều kiện của đề', 'Lập số lớn nhất/bé nhất của ba thẻ nhưng bỏ điều kiện thêm của đề (hàng chục là 0, lớn hơn 400...).', 'Thẻ 0, 5, 9, hàng chục là 0 → 950', 'khai_niem', array['NDB02807']::text[], false, true),
 ('R483', 'Lập số từ thẻ số: đảo yêu cầu lớn nhất ↔ bé nhất', 'Đọc nhầm yêu cầu: lập số bé nhất khi đề hỏi lớn nhất (hoặc ngược lại) vẫn theo điều kiện của đề.', 'Thẻ 2, 6, 8, lớn nhất bé hơn 700 → 268', 'khai_niem', array['NDB02807']::text[], false, true),
 ('R485', 'Dãy số: số thứ hai nhảy gấp ba bước', 'Viết đúng số đầu rồi nhảy sai khoảng cách: số kế tiếp cách số trước 3 bước.', 'Dãy 14; 21; 28 → 35; 49', 'tinh', array['NDB02045','NDB02046','NDB02031']::text[], false, true),
 ('R486', 'Ba số liên tiếp: đặt số đã cho sai vị trí', 'Viết đủ ba số liên tiếp nhưng đặt số cho trước vào sai vị trí (đầu/giữa/cuối).', '..., 40, ... → 40, 41, 42', 'khai_niem', array['NDB02031']::text[], false, true),
 ('R487', 'Lập số từ thẻ số: số thỏa điều kiện nhưng không phải lớn nhất/bé nhất', 'Lập đúng số theo điều kiện nhưng dừng ở số thỏa mãn liền kề trong danh sách, không chọn số lớn nhất/bé nhất.', 'Thẻ 1, 4, 7, bé nhất lớn hơn 400 → 471', 'khai_niem', array['NDB02807']::text[], false, true)
